<template>
  <div class="space-y-6">
    <div class="flex flex-wrap items-start justify-between gap-4"><div><h2 class="text-xl font-bold text-gray-800">Periode Penghargaan</h2><p class="text-sm text-gray-500 mt-1">Jadwal, tahapan pelaksanaan, dan data penghargaan per periode.</p></div><button v-if="admin" @click="openPeriod()" class="primary">Tambah periode</button></div>
    <div v-if="error" role="alert" class="bg-red-50 border border-red-200 rounded-xl p-4 text-sm text-red-700">{{ error }} <button @click="load" class="underline ml-2">Muat ulang</button></div>
    <p v-if="loading" role="status" class="text-sm text-gray-500">Memuat periode…</p>
    <div v-else-if="!periods.length" class="panel text-center py-12"><p class="font-semibold text-gray-700">Belum ada periode penghargaan</p><p class="text-sm text-gray-500 mt-2">Administrator dapat membuat periode dan mengaitkan data yang sudah tersedia.</p></div>
    <div v-if="periods.length" class="grid xl:grid-cols-3 gap-6 items-start">
      <div class="space-y-3 xl:sticky xl:top-20">
        <label class="block text-xs font-medium text-gray-600">Cari periode<input v-model="search" type="search" class="field mt-2" placeholder="Nama atau tahun periode" /></label>
        <button v-for="p in filtered" :key="p.id" @click="select(p.id)" class="panel text-left w-full transition hover:border-blue-300" :class="selected?.id===p.id?'border-blue-400 ring-1 ring-blue-100':''">
          <div class="flex items-start justify-between gap-3"><h3 class="font-semibold text-sm text-gray-800 break-words">{{ p.nama }}</h3><span class="badge shrink-0" :class="statusClass(p.status)">{{ p.status }}</span></div>
          <p class="text-xs text-gray-500 mt-2 mb-4">{{ date(p.start_date) }} – {{ date(p.end_date) }}</p><PeriodProgress :progress="p.progress" :label="'Progres '+p.nama" />
          <p class="text-xs text-gray-500 mt-3">{{ p.applicants.total }} pengusul<span v-if="p.progress.terlambat" class="text-red-600"> · {{ p.progress.terlambat }} tahap melewati jadwal</span></p>
        </button><p v-if="!filtered.length" class="text-sm text-gray-500">Periode tidak ditemukan.</p>
      </div>
      <div v-if="selected" class="xl:col-span-2 space-y-6 min-w-0">
        <section class="panel">
          <div class="flex flex-wrap justify-between gap-3"><div><h3 class="font-bold text-lg text-gray-800">{{ selected.nama }}</h3><p class="text-xs text-gray-500 mt-1">Tahun {{ selected.tahun }} · {{ date(selected.start_date) }} – {{ date(selected.end_date) }}</p></div><button v-if="admin" @click="openPeriod(selected)" class="secondary">Pengaturan periode</button></div>
          <div class="mt-5"><PeriodProgress :progress="selected.progress" /></div><p class="text-xs text-gray-500 mt-3 leading-relaxed">Progres berdasarkan tahap yang dikonfirmasi Admin. Tahap perbaikan yang tidak diperlukan dikecualikan dari perhitungan. Jadwal dihitung per {{ date(selected.as_of_date) }}.</p>
          <p v-if="selected.catatan" class="mt-4 text-sm text-gray-600 whitespace-pre-wrap">{{ selected.catatan }}</p>
          <div class="grid grid-cols-2 sm:grid-cols-4 gap-3 mt-5"><div v-for="k in indicators" :key="k.key" class="bg-gray-50 rounded-xl p-3"><p class="text-xs text-gray-500">{{ k.label }}</p><p class="text-xl font-bold text-gray-800 mt-1">{{ selected.applicants[k.key] }}</p></div></div>
          <div class="mt-5 space-y-3"><div v-for="k in verification" :key="k.key"><div class="flex justify-between gap-3 text-xs text-gray-600 mb-1.5"><span>{{ k.label }}</span><span>{{ selected.applicants[k.key] }} / {{ selected.applicants.total }}</span></div><div class="h-1.5 rounded-full bg-gray-100 overflow-hidden"><div class="bg-green-500 h-full rounded-full" :style="{width:(selected.applicants.total?selected.applicants[k.key]/selected.applicants.total*100:0)+'%'}"></div></div></div></div>
          <router-link :to="dashboardPath+'?periode_id='+selected.id" class="inline-block text-sm text-blue-600 hover:underline mt-5">Lihat dashboard periode →</router-link>
        </section>
        <section class="panel"><h3 class="font-semibold text-sm text-gray-800 mb-5">Tahapan pelaksanaan</h3><ol class="space-y-5"><li v-for="(s,index) in selected.stages" :key="s.kode" class="flex gap-3"><span class="w-8 h-8 rounded-full shrink-0 flex items-center justify-center text-xs font-bold" :class="s.status==='Selesai'?'bg-green-100 text-green-700':s.status==='Berjalan'?'bg-blue-100 text-blue-700':'bg-gray-100 text-gray-500'">{{ s.status==='Selesai'?'✓':index+1 }}</span><div class="flex-1 min-w-0 border-b border-gray-100 pb-5"><div class="flex flex-wrap justify-between gap-2"><h4 class="text-sm font-semibold text-gray-800">{{ s.label }} <span v-if="s.optional" class="font-normal text-xs text-gray-400">Opsional</span></h4><span class="badge" :class="statusClass(s.status)">{{ s.status }}</span></div><p class="text-xs text-gray-500 mt-2">{{ s.start_date?date(s.start_date):'Mulai belum dijadwalkan' }} – {{ s.end_date?date(s.end_date):'Selesai belum dijadwalkan' }}</p><p v-if="late(s)" class="text-xs text-red-600 mt-1">Melewati jadwal penyelesaian</p><p v-if="s.catatan" class="text-sm text-gray-600 mt-2 whitespace-pre-wrap break-words">{{ s.catatan }}</p><button v-if="admin&&selected.status!=='Selesai'" @click="openStage(s)" class="text-xs text-blue-600 hover:underline mt-3">Atur jadwal dan status</button></div></li></ol></section>
        <section class="panel"><div class="flex flex-wrap justify-between gap-3 mb-4"><div><h3 class="font-semibold text-sm text-gray-800">Data terkait periode</h3><p class="text-xs text-gray-500 mt-1">Data lama tetap tanpa periode sampai dikaitkan oleh Admin.</p></div></div><div class="grid grid-cols-2 sm:grid-cols-3 gap-3"><div v-for="m in modules" :key="m.key" class="border border-gray-100 rounded-xl p-3"><p class="text-xs text-gray-500">{{ m.label }}</p><p class="font-bold text-lg text-gray-800 mt-1">{{ selected.documents[m.key] }}</p><button v-if="admin&&selected.status!=='Selesai'" @click="openItems(m.key)" class="text-xs text-blue-600 hover:underline mt-2">Kelola data</button></div></div><p class="text-xs text-gray-400 mt-4">SK tersedia dihitung dari metadata file, bukan konfirmasi penetapan atau serah terima penghargaan.</p></section>
      </div>
    </div>

    <Teleport to="body"><div v-if="modal" class="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50"><section role="dialog" aria-modal="true" aria-labelledby="period-modal-title" class="bg-white rounded-2xl shadow-xl w-full max-w-2xl max-h-[90vh] overflow-y-auto p-6">
      <div class="flex justify-between gap-3 mb-5"><h3 id="period-modal-title" class="font-bold text-gray-800">{{ modal==='period'?(periodForm.id?'Pengaturan periode':'Tambah periode'):modal==='stage'?'Atur tahap pelaksanaan':'Kelola '+moduleLabel }}</h3><button @click="closeModal" :disabled="saving" aria-label="Tutup dialog" class="text-gray-500">✕</button></div>
      <p v-if="modalError" role="alert" class="text-red-700 text-sm bg-red-50 rounded-xl p-3 mb-4">{{ modalError }}</p>
      <form v-if="modal==='period'" @submit.prevent="savePeriod" class="space-y-4"><label class="label">Nama periode<input v-model="periodForm.nama" required maxlength="150" class="field" /></label><div class="grid sm:grid-cols-2 gap-4"><label class="label">Tahun penyelenggaraan<input v-model.number="periodForm.tahun" required type="number" min="1900" max="9999" class="field" /></label><label class="label">Status periode<select aria-label="Status periode" v-model="periodForm.status" class="field"><option>Persiapan</option><option>Aktif</option><option v-if="periodForm.id">Selesai</option></select></label><label class="label">Tanggal mulai<input v-model="periodForm.start_date" required type="date" class="field" /></label><label class="label">Tanggal selesai<input v-model="periodForm.end_date" required type="date" :min="periodForm.start_date" class="field" /></label></div><label class="label">Catatan<textarea v-model="periodForm.catatan" rows="3" maxlength="5000" class="field"></textarea></label><p class="text-xs text-gray-500">Periode Selesai dikunci. Seluruh tahap yang diperlukan harus selesai sebelum periode ditutup. Untuk koreksi, ubah kembali menjadi Aktif.</p><div class="flex flex-wrap justify-between gap-3"><button v-if="periodForm.id&&selected.status==='Persiapan'&&!Object.values(selected.documents).some(Boolean)" type="button" @click="deletePeriod" :disabled="saving" class="text-red-600 text-sm">Hapus periode kosong</button><button class="primary ml-auto" :disabled="saving">{{ saving?'Menyimpan…':'Simpan periode' }}</button></div></form>
      <form v-if="modal==='stage'" @submit.prevent="saveStage" class="space-y-4"><p class="text-sm font-semibold text-gray-700">{{ stageForm.label }}</p><label class="label">Status tahap<select aria-label="Status tahap" v-model="stageForm.status" class="field"><option>Belum dimulai</option><option>Berjalan</option><option>Selesai</option><option v-if="stageForm.optional">Tidak diperlukan</option></select></label><div class="grid sm:grid-cols-2 gap-4"><label class="label">Tanggal mulai tahap<input v-model="stageForm.start_date" type="date" :min="selected.start_date" :max="selected.end_date" class="field" /></label><label class="label">Tanggal selesai tahap<input v-model="stageForm.end_date" type="date" :min="stageForm.start_date||selected.start_date" :max="selected.end_date" class="field" /></label></div><label class="label">Catatan hasil pelaksanaan<textarea v-model="stageForm.catatan" :required="stageForm.status==='Selesai'" maxlength="5000" rows="4" class="field"></textarea></label><p class="text-xs text-gray-500">Pengaturan status mengubah progres pelaksanaan. Catatan hasil wajib diisi untuk tahap Selesai. Keputusan verifikasi pengusul tetap dikelola pada halaman verifikasi.</p><div class="text-right"><button class="primary" :disabled="saving">{{ saving?'Menyimpan…':'Simpan tahap' }}</button></div></form>
      <div v-if="modal==='items'" class="space-y-4"><div class="flex flex-wrap gap-2"><button @click="itemScope='assigned';itemPage=1;loadItems()" class="secondary" :class="itemScope==='assigned'&&'bg-blue-50 text-blue-700'">Sudah terkait ({{ selected.documents[itemModule] }})</button><button @click="itemScope='available';itemPage=1;loadItems()" class="secondary" :class="itemScope==='available'&&'bg-blue-50 text-blue-700'">Belum memiliki periode</button></div><form @submit.prevent="itemPage=1;loadItems()" class="flex gap-2"><input v-model="itemSearch" aria-label="Cari data periode" type="search" placeholder="Cari nama atau instansi" class="field" /><button class="secondary">Cari</button></form><p class="text-xs text-gray-500">{{ itemTotal }} data ditemukan. Satu record hanya dapat dikaitkan ke satu periode. Pilih data secara eksplisit; tahun tidak digunakan untuk mengaitkan otomatis.</p><p v-if="itemLoading" role="status" class="text-sm text-gray-500">Memuat data…</p><div v-else class="divide-y divide-gray-100"><label v-for="row in itemRows" :key="row.id" class="flex items-start gap-3 py-3"><input v-model="checked" type="checkbox" :value="row.id" class="rounded mt-1 border-gray-300 text-blue-600" /><div class="min-w-0"><p class="text-sm font-medium text-gray-800 break-words">{{ row.nama||'Tanpa nama' }}</p><p class="text-xs text-gray-500 break-words mt-1">{{ row.keterangan||'—' }} · {{ row.tanggal||'Tanpa tanggal' }}</p></div></label><p v-if="!itemRows.length" class="text-sm text-gray-500 py-6 text-center">Tidak ada data untuk pilihan ini.</p></div><div class="flex flex-wrap items-center justify-between gap-3"><button @click="itemPage--;loadItems()" :disabled="itemPage<=1||itemLoading" class="secondary">Sebelumnya</button><span class="text-xs text-gray-500">Halaman {{ itemPage }} / {{ Math.max(1,Math.ceil(itemTotal/25)) }}</span><button @click="itemPage++;loadItems()" :disabled="itemPage*25>=itemTotal||itemLoading" class="secondary">Berikutnya</button></div><button @click="saveItems" :disabled="!checked.length||saving||itemLoading" class="primary w-full">{{ saving?'Menyimpan…':(itemScope==='available'?'Kaitkan ':'Lepaskan ')+checked.length+' data terpilih' }}</button></div>
    </section></div></Teleport>
  </div>
</template>

<script setup>
import {ref,computed,onMounted} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {useAuthStore} from '../../stores/auth';
import api from '../../api/client';
import PeriodProgress from '../../components/shared/PeriodProgress.vue';
const auth=useAuthStore(),route=useRoute(),router=useRouter();
const admin=computed(()=>auth.user?.level==='Admin');
const dashboardPath=computed(()=>admin.value?'/admin/executive':'/pimpinan');
const periods=ref([]),selected=ref(null),search=ref(''),loading=ref(false),error=ref('');
const filtered=computed(()=>periods.value.filter(p=>(p.nama+' '+p.tahun).toLowerCase().includes(search.value.toLowerCase())));
const modal=ref(''),modalError=ref(''),saving=ref(false),periodForm=ref({}),stageForm=ref({});
const modules=[{key:'individu',label:'Pengusul'},{key:'pemberitahuan',label:'Surat pemberitahuan'},{key:'usulan',label:'Surat usulan'},{key:'distribusi',label:'Distribusi / serah terima'},{key:'laporan',label:'Laporan kegiatan'}];
const indicators=[{key:'total',label:'Pengusul terkait'},{key:'lolos',label:'Lolos verifikasi'},{key:'perbaikan',label:'Perlu perbaikan'},{key:'sk_tersedia',label:'SK tersedia'}];
const verification=[{key:'data_disetujui',label:'Verifikasi data disetujui'},{key:'berkas_disetujui',label:'Verifikasi berkas disetujui'}];
const itemModule=ref('individu'),itemScope=ref('assigned'),itemPage=ref(1),itemSearch=ref(''),itemRows=ref([]),itemTotal=ref(0),itemLoading=ref(false),checked=ref([]);
const moduleLabel=computed(()=>modules.find(m=>m.key===itemModule.value)?.label);
const date=v=>v?new Intl.DateTimeFormat('id-ID',{dateStyle:'medium',timeZone:'UTC'}).format(new Date(v+'T00:00:00Z')):'—';
const statusClass=s=>s==='Selesai'?'bg-green-50 text-green-700':s==='Aktif'||s==='Berjalan'?'bg-blue-50 text-blue-700':'bg-gray-100 text-gray-600';
const late=s=>s.end_date&&s.end_date<selected.value.as_of_date&&!['Selesai','Tidak diperlukan'].includes(s.status);
async function load(){loading.value=true;error.value='';try{const {data}=await api.get('/periods');periods.value=data;const id=selected.value?.id||Number(route.query.id);selected.value=data.find(p=>p.id===id)||data[0]||null;}catch(e){error.value=e.response?.data?.error||'Gagal mengambil periode';}finally{loading.value=false;}}
function select(id){selected.value=periods.value.find(p=>p.id===id);router.replace({query:{id}});}
function openPeriod(p){modalError.value='';periodForm.value=p?{id:p.id,nama:p.nama,tahun:p.tahun,start_date:p.start_date,end_date:p.end_date,status:p.status,catatan:p.catatan,revision:p.revision}:{nama:'',tahun:new Date().getFullYear(),start_date:'',end_date:'',status:'Persiapan',catatan:''};modal.value='period';}
function openStage(s){modalError.value='';stageForm.value={...s,start_date:s.start_date||'',end_date:s.end_date||''};modal.value='stage';}
function closeModal(){if(!saving.value)modal.value='';}
function replace(p){const index=periods.value.findIndex(x=>x.id===p.id);if(index<0)periods.value.unshift(p);else periods.value.splice(index,1,p);selected.value=p;}
async function mutate(fn){if(saving.value)return;saving.value=true;modalError.value='';try{await fn();}catch(e){modalError.value=e.response?.data?.error||'Gagal menyimpan perubahan';if(e.response?.status===409){await load();modalError.value+=' Tutup dialog dan buka kembali untuk memeriksa data terbaru.';}}finally{saving.value=false;}}
async function savePeriod(){await mutate(async()=>{const {id,...body}=periodForm.value;const {data}=await (id?api.put('/periods/'+id,body):api.post('/periods',body));replace(data);modal.value='';});}
async function saveStage(){await mutate(async()=>{const s=stageForm.value;const {data}=await api.put(`/periods/${selected.value.id}/stages/${s.kode}`,{status:s.status,start_date:s.start_date||null,end_date:s.end_date||null,catatan:s.catatan,revision:selected.value.revision});replace(data);modal.value='';});}
async function deletePeriod(){await mutate(async()=>{await api.delete('/periods/'+selected.value.id,{data:{revision:selected.value.revision}});selected.value=null;modal.value='';await load();});}
async function openItems(module){itemModule.value=module;itemScope.value='assigned';itemPage.value=1;itemSearch.value='';modalError.value='';modal.value='items';await loadItems();}
let itemRequest=0;
async function loadItems(){const request=++itemRequest;itemLoading.value=true;checked.value=[];try{const {data}=await api.get(`/periods/${selected.value.id}/items/${itemModule.value}`,{params:{scope:itemScope.value,page:itemPage.value,search:itemSearch.value}});if(request!==itemRequest)return;itemRows.value=data.rows;itemTotal.value=data.total;}catch(e){if(request===itemRequest)modalError.value=e.response?.data?.error||'Gagal mengambil data';}finally{if(request===itemRequest)itemLoading.value=false;}}
async function saveItems(){await mutate(async()=>{const {data}=await api.put(`/periods/${selected.value.id}/items/${itemModule.value}`,{ids:checked.value,action:itemScope.value==='available'?'assign':'remove',revision:selected.value.revision});replace(data);await loadItems();});}
onMounted(load);
</script>

<style scoped>
.panel{@apply bg-white border border-gray-100 rounded-2xl shadow-sm p-5;}
.primary{@apply bg-blue-600 text-white text-sm font-medium rounded-xl px-4 py-2.5 hover:bg-blue-700 disabled:opacity-40;}
.secondary{@apply text-sm border border-gray-300 rounded-xl px-3 py-2 hover:bg-gray-50 disabled:opacity-40;}
.field{@apply block w-full rounded-xl border-gray-300 text-sm focus:border-blue-500 focus:ring-blue-100;}
.label{@apply block text-xs font-medium text-gray-600;}.label .field{@apply mt-2;}
.badge{@apply text-xs font-medium px-2.5 py-1 rounded-full;}
</style>
